// populateHosts adds container hostnames for other nodes of a lab to SR Linux /etc/hosts file
// to mitigate the fact that srlinux uses non default netns for management and thus
// can't leverage docker DNS service.
func (n *srl) populateHosts(ctx context.Context, nodes map[string]clabnodes.Node) error {
	hosts, err := n.Runtime.GetHostsPath(ctx, n.Cfg.LongName)
	if err != nil {
		log.Warnf("Unable to locate /etc/hosts file for srl node %v: %v", n.Cfg.ShortName, err)
		return err
	}

	var entriesv4, entriesv6 bytes.Buffer

	const (
		v4Prefix = "###### CLAB-v4-START ######"
		v4Suffix = "###### CLAB-v4-END ######"
		v6Prefix = "###### CLAB-v6-START ######"
		v6Suffix = "###### CLAB-v6-END ######"
	)
	fmt.Fprintf(&entriesv4, "\n%s\n", v4Prefix)
	fmt.Fprintf(&entriesv6, "\n%s\n", v6Prefix)

	for node, params := range nodes {
		if v4 := params.Config().MgmtIPv4Address; v4 != "" {
			fmt.Fprintf(&entriesv4, "%s\t%s\n", v4, node)
		}

		if v6 := params.Config().MgmtIPv6Address; v6 != "" {
			fmt.Fprintf(&entriesv6, "%s\t%s\n", v6, node)
		}
	}

	fmt.Fprintf(&entriesv4, "%s\n", v4Suffix)
	fmt.Fprintf(&entriesv6, "%s\n", v6Suffix)

	// world-writable for container /etc/hosts
	const hostsFilePerm = 0o666

	file, err := os.OpenFile(hosts, os.O_APPEND|os.O_WRONLY, hostsFilePerm) // skipcq: GSC-G302
	if err != nil {
		log.Warnf("Unable to open /etc/hosts file for srl node %v: %v", n.Cfg.ShortName, err)
		return err
	}

	_, err = file.Write(entriesv4.Bytes())
	if err != nil {
		return err
	}

	_, err = file.Write(entriesv6.Bytes())
	if err != nil {
		return err
	}

	return file.Close()
}

func (n *srl) GetMappedInterfaceName(ifName string) (string, error) {
	captureGroups, err := clabutils.GetRegexpCaptureGroups(n.InterfaceRegexp, ifName)
	if err != nil {
		return "", err
	}

	indexGroups := []string{"linecard", "port", "channel"}
	parsedIndices := make(map[string]int)
	foundIndices := make(map[string]bool)

	for _, indexKey := range indexGroups {
		if index, found := captureGroups[indexKey]; found && index != "" {
			foundIndices[indexKey] = true

			parsedIndices[indexKey], err = strconv.Atoi(index)
			if err != nil {
				return "", fmt.Errorf(
					"%q parsed %s index %q could not be cast to an integer",
					ifName,
					indexKey,
					index,
				)
			}

			if parsedIndices[indexKey] < 1 {
				return "", fmt.Errorf(
					"%q parsed %q index %q does not match requirement >= 1",
					ifName,
					indexKey,
					index,
				)
			}
		} else {
			foundIndices[indexKey] = false
		}
	}

	if foundIndices["linecard"] && foundIndices["port"] {
		if foundIndices["channel"] {
			return fmt.Sprintf("e%d-%d-%d", parsedIndices["linecard"],
				parsedIndices["port"], parsedIndices["channel"]), nil
		} else {
			return fmt.Sprintf("e%d-%d", parsedIndices["linecard"], parsedIndices["port"]), nil
		}
	} else {
		return "", fmt.Errorf("%q missing linecard or port index", ifName)
	}
}

// CheckInterfaceName checks if a name of the interface referenced in the topology file correct.
func (n *srl) CheckInterfaceName() error {
	nm := strings.ToLower(n.Cfg.NetworkMode)

	err := n.CheckInterfaceOverlap()
	if err != nil {
		return err
	}

	for _, e := range n.Endpoints {
		if !normalizedInterfaceRegexp.MatchString(e.GetIfaceName()) {
			return fmt.Errorf(
				"nokia sr linux interface name %q doesn't match the required pattern: %s",
				e.GetIfaceName(),
				n.InterfaceHelp,
			)
		}

		if e.GetIfaceName() == mgmt0InterfaceName && nm != "none" {
			return fmt.Errorf(
				"mgmt0 interface name is not allowed for %s node when network mode is not set to none",
				n.Cfg.ShortName,
			)
		}
	}

	return nil
}

// createRepoFiles creates apt/ym repository files
// to enable srl nodes to install ndk apps.
func (n *srl) createRepoFiles() error {
	yumRepo := `[srlinux]
name=SR Linux NDK apps
baseurl=https://srlinux.fury.site/yum/
enabled=1
gpgcheck=0`

	aptRepo := `deb [trusted=yes] https://srlinux.fury.site/apt/ /`

	yumPath := n.Cfg.LabDir + "/yum.repo"

	err := clabutils.CreateFile(yumPath, yumRepo)
	if err != nil {
		return err
	}

	aptPath := n.Cfg.LabDir + "/apt.list"

	err = clabutils.CreateFile(aptPath, aptRepo)
	if err != nil {
		return err
	}

	// mount srlinux repository files
	n.Cfg.Binds = append(
		n.Cfg.Binds,
		yumPath+":/etc/yum.repos.d/srlinux.repo:ro",
		aptPath+":/etc/apt/sources.list.d/srlinux.list:ro")

	return nil
}

package core

import (
	"context"
	"fmt"
	"sort"
	"strings"

	clabconstants "github.com/srl-labs/containerlab/constants"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabruntime "github.com/srl-labs/containerlab/runtime"
)

type runtimeNodeGroup struct {
	name               string
	containers         []clabruntime.GenericContainer
	distributed        bool
	external           bool
	rootNamespaceBased bool
}

func (c *CLab) runtimeNodeGroups(
	ctx context.Context,
) (map[string]*runtimeNodeGroup, error) {
	containers, err := c.ListContainers(ctx, WithListLabName(c.Config.Name))
	if err != nil {
		return nil, err
	}

	result := make(map[string]*runtimeNodeGroup)
	var duplicates []string

	for _, ctr := range containers {
		if ctr.Labels[clabconstants.ToolType] != "" {
			continue
		}

		nodeName := ctr.Labels[clabconstants.NodeName]
		if nodeName == "" {
			continue
		}

		groupName := ctr.Labels[clabconstants.RootNodeName]
		distributed := groupName != ""
		if groupName == "" {
			groupName = nodeName
		}

		group, exists := result[groupName]
		if !exists {
			group = &runtimeNodeGroup{
				name:        groupName,
				distributed: distributed,
			}
			result[groupName] = group
		}
		group.containers = append(group.containers, ctr)
		group.distributed = group.distributed || distributed

		if !group.distributed && len(group.containers) > 1 {
			duplicates = append(duplicates, nodeName)
			continue
		}
	}

	// Pre-existing resources have no containerlab labels, but still participate in apply.
	for nodeName, node := range c.Nodes {
		cfg := node.Config()
		if cfg == nil {
			continue
		}
		if _, exists := result[nodeName]; exists {
			continue
		}
		if cfg.IsRootNamespaceBased {
			result[nodeName] = &runtimeNodeGroup{
				name:               nodeName,
				rootNamespaceBased: true,
			}
			continue
		}
		if !cfg.SkipUniquenessCheck || node.GetContainerStatus(ctx) == clabruntime.NotFound {
			continue
		}
		result[nodeName] = &runtimeNodeGroup{name: nodeName, external: true}
	}

	if len(duplicates) > 0 {
		sort.Strings(duplicates)
		return nil, fmt.Errorf(
			"apply supports only single-container nodes, found multiple containers for nodes: %s",
			strings.Join(duplicates, ", "),
		)
	}

	for _, group := range result {
		sort.Slice(group.containers, func(i, j int) bool {
			return runtimeContainerLess(group.containers[i], group.containers[j])
		})
	}

	return result, nil
}

// NeedsInitialDeploy reports whether the lab has no runtime state yet, i.e. whether
// Deploy would perform a fresh deployment instead of reconciling a running lab.
func (c *CLab) NeedsInitialDeploy(ctx context.Context) (bool, error) {
	if c.LabRuntime != nil {
		checker, ok := c.LabRuntime.(clablabruntime.LabExistenceChecker)
		if !ok {
			return false, fmt.Errorf(
				"lab runtime %q cannot determine whether the lab already exists",
				c.globalRuntimeName,
			)
		}
		exists, err := checker.LabExists(ctx, clablabruntime.InspectRequest{
			Name:     c.Config.Name,
			Identity: c.labRuntimeIdentity,
		})

		return !exists, err
	}

	currentNodes, err := c.runtimeNodeGroups(ctx)
	if err != nil {
		return false, err
	}

	return c.needsInitialDeploy(currentNodes)
}

func (c *CLab) needsInitialDeploy(currentNodes map[string]*runtimeNodeGroup) (bool, error) {
	if len(currentNodes) == 0 {
		return true, nil
	}
	for _, node := range currentNodes {
		if !node.external && !node.rootNamespaceBased {
			return false, nil
		}
	}

	state, err := c.LoadState()
	return state == nil, err
}

func (c *CLab) setMgmtBridgeFromRuntime(
	currentNodes map[string]*runtimeNodeGroup,
) error {
	if c.Config.Mgmt.Bridge != "" {
		return nil
	}

	var bridge string
	for _, runtimeNode := range currentNodes {
		for _, ctr := range runtimeNode.containers {
			// only containers attached to the default management network, or
			// without a runtime network, carry the default network's bridge
			// label. Unknown networks, e.g. ones dropped from the mgmt list,
			// must not contribute their bridge.
			switch ctr.NetworkName {
			case "", c.Config.Mgmt.Network:
			default:
				continue
			}
			ctrBridge := ctr.Labels[clabconstants.NodeMgmtNetBr]
			if ctrBridge == "" {
				continue
			}
			if bridge == "" {
				bridge = ctrBridge
				continue
			}
			if bridge != ctrBridge {
				return fmt.Errorf(
					"runtime lab has conflicting management bridge labels: %q and %q",
					bridge,
					ctrBridge,
				)
			}
		}
	}

	if bridge != "" {
		c.Config.Mgmt.Bridge = bridge
	}

	return nil
}

func (c *CLab) updateRuntimeInfoForExistingNodes(ctx context.Context) error {
	for _, nodeName := range sortedNodeNames(c.Nodes) {
		node := c.Nodes[nodeName]
		if node.GetContainerStatus(ctx) == clabruntime.NotFound {
			continue
		}
		if err := node.UpdateConfigWithRuntimeInfo(ctx); err != nil {
			return fmt.Errorf("failed to update runtime info for node %q: %w", nodeName, err)
		}
	}

	return nil
}

func sortedRuntimeNodeGroupNames(nodes map[string]*runtimeNodeGroup) []string {
	names := make([]string, 0, len(nodes))
	for name := range nodes {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func runtimeContainerNodeName(ctr clabruntime.GenericContainer) string {
	if name := ctr.Labels[clabconstants.NodeName]; name != "" {
		return name
	}
	if len(ctr.Names) > 0 {
		return ctr.Names[0]
	}
	return ctr.ID
}

func runtimeContainerLess(a, b clabruntime.GenericContainer) bool {
	// internal holders own the network namespace of the other containers in the group,
	// so they sort first to be deleted last.
	aInternal := a.Labels[clabconstants.InternalNode] == "true"
	bInternal := b.Labels[clabconstants.InternalNode] == "true"
	if aInternal != bInternal {
		return aInternal
	}

	aName := runtimeContainerNodeName(a)
	bName := runtimeContainerNodeName(b)

	aOrder := runtimeComponentSortOrder(aName)
	bOrder := runtimeComponentSortOrder(bName)
	if aOrder != bOrder {
		return aOrder < bOrder
	}

	return aName < bName
}

func runtimeComponentSortOrder(name string) int {
	idx := strings.LastIndex(name, "-")
	if idx < 0 || idx == len(name)-1 {
		return 0
	}

	slot := strings.ToUpper(name[idx+1:])
	if len(slot) == 1 && slot[0] >= 'A' && slot[0] <= 'Z' {
		return 100 - int(slot[0])
	}

	var n int
	for _, r := range slot {
		if r < '0' || r > '9' {
			return 0
		}
		n = n*10 + int(r-'0')
	}

	return n
}

