func (c *CLab) addMgmtNetworksFromContainers(containers []clabruntime.GenericContainer) {
	for _, ctr := range containers {
		switch name := ctr.NetworkName; name {
		case "", "unknown", "bridge", "host", "none":
		default:
			if c.mgmtNetByNetwork(name).Network == name {
				continue
			}
			c.Config.MgmtNetworks = append(c.Config.MgmtNetworks, &clabtypes.MgmtNet{
				Network:        name,
				Bridge:         ctr.Labels[clabconstants.NodeMgmtNetBr],
				ExternalAccess: new(true),
			})
		}
	}
}

// mgmtNetworksForCleanup returns the management networks to delete on destroy:
// the topology-defined ones plus any network a previous deployment recorded in
// the lab state but that the current topology no longer defines. Without the
// state record a network dropped from the mgmt list would never be removed.
func (c *CLab) mgmtNetworksForCleanup() clabtypes.MgmtNetworks {
	networks := c.allMgmtNetworks()

	state, err := c.LoadState()
	if err != nil {
		log.Warn("Unable to load the management networks recorded in the lab state", "error", err)
		return networks
	}
	if state == nil {
		return networks
	}

	defined := make(map[string]bool, len(networks))
	for _, m := range networks {
		defined[m.Network] = true
	}
	for _, name := range state.MgmtNetworks {
		if defined[name] {
			continue
		}
		defined[name] = true
		// ExternalAccess mirrors the default every management network gets, so
		// the forwarding rule installed for the network is cleaned up too.
		networks = append(networks, &clabtypes.MgmtNet{
			Network:        name,
			ExternalAccess: new(true),
		})
	}

	return networks
}

func (c *CLab) deleteApplyNodes(ctx context.Context, plan *applyPlan) error {
	nodeNames := make([]string, 0, len(plan.deletedNodeSet)+len(plan.recreatedNodeSet))
	for nodeName := range plan.deletedNodeSet {
		nodeNames = append(nodeNames, nodeName)
	}
	for nodeName := range plan.recreatedNodeSet {
		nodeNames = append(nodeNames, nodeName)
	}
	sort.Strings(nodeNames)

	hookNodes := make([]clabnodes.Node, 0, len(nodeNames))
	var tailscaleContainers []clabruntime.GenericContainer
	for _, nodeName := range nodeNames {
		runtimeNode := plan.currentNodes[nodeName]
		if runtimeNode == nil {
			return fmt.Errorf("runtime node %q not found", nodeName)
		}
		if runtimeNode.external || runtimeNode.rootNamespaceBased {
			continue
		}
		if len(runtimeNode.containers) > 0 &&
			runtimeNode.containers[0].Labels[clabconstants.NodeKind] == clabnodestailscale.KindName {
			tailscaleContainers = append(tailscaleContainers, runtimeNode.containers...)
			continue
		}
		if node, ok := c.Nodes[nodeName]; ok {
			hookNodes = append(hookNodes, node)
		}
	}
	var logoutWg sync.WaitGroup
	for _, ctr := range tailscaleContainers {
		logoutWg.Go(func() { c.logoutTailscaleContainer(ctx, ctr) })
	}
	c.preDestroyNodes(ctx, hookNodes, 0)
	logoutWg.Wait()

	for _, nodeName := range nodeNames {
		runtimeNode := plan.currentNodes[nodeName]
		if runtimeNode.external || runtimeNode.rootNamespaceBased {
			continue
		}

		for i := len(runtimeNode.containers) - 1; i >= 0; i-- {
			ctr := runtimeNode.containers[i]
			if len(ctr.Names) == 0 {
				return fmt.Errorf("runtime container for node %q has no name", nodeName)
			}

			runtime := ctr.Runtime
			if runtime == nil {
				runtime = c.globalRuntime()
			}

			action := "Deleting node"
			if _, recreate := plan.recreatedNodeSet[nodeName]; recreate {
				action = "Deleting node for recreate"
			}
			log.Info(action, "node", nodeName, "container", ctr.Names[0])
			if err := runtime.DeleteContainer(ctx, ctr.Names[0]); err != nil {
				return fmt.Errorf("failed deleting node %q: %w", nodeName, err)
			}

			_ = clabutils.DeleteNetnsSymlink(ctr.Names[0])
		}
	}

	return nil
}

// preDestroyNodes runs the PreDestroy stage of the given nodes concurrently, before any of them
// is deleted. Nodes without a container are skipped. A workers value of 0 runs all hooks at once.
func (*CLab) preDestroyNodes(ctx context.Context, nodes []clabnodes.Node, workers uint) {
	if workers == 0 || workers > uint(len(nodes)) {
		workers = uint(len(nodes))
	}

	sem := make(chan struct{}, workers)
	wg := new(sync.WaitGroup)

	for _, n := range nodes {
		wg.Add(1)
		sem <- struct{}{}

package core

import (
	"context"
	"fmt"
	"sort"
	"strings"

	clabconstants "github.com/srl-labs/containerlab/constants"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabruntime "github.com/srl-labs/containerlab/runtime"
)

type runtimeNodeGroup struct {
	name               string
	containers         []clabruntime.GenericContainer
	distributed        bool
	external           bool
	rootNamespaceBased bool
}

func (c *CLab) runtimeNodeGroups(
	ctx context.Context,
) (map[string]*runtimeNodeGroup, error) {
	containers, err := c.ListContainers(ctx, WithListLabName(c.Config.Name))
	if err != nil {
		return nil, err
	}

	result := make(map[string]*runtimeNodeGroup)
	var duplicates []string

	for _, ctr := range containers {
		if ctr.Labels[clabconstants.ToolType] != "" {
			continue
		}

		nodeName := ctr.Labels[clabconstants.NodeName]
		if nodeName == "" {
			continue
		}

		groupName := ctr.Labels[clabconstants.RootNodeName]
		distributed := groupName != ""
		if groupName == "" {
			groupName = nodeName
		}

		group, exists := result[groupName]
		if !exists {
			group = &runtimeNodeGroup{
				name:        groupName,
				distributed: distributed,
			}
			result[groupName] = group
		}
		group.containers = append(group.containers, ctr)
		group.distributed = group.distributed || distributed

		if !group.distributed && len(group.containers) > 1 {
			duplicates = append(duplicates, nodeName)
			continue
		}
	}

	// Pre-existing resources have no containerlab labels, but still participate in apply.
	for nodeName, node := range c.Nodes {
		cfg := node.Config()
		if cfg == nil {
			continue
		}
		if _, exists := result[nodeName]; exists {
			continue
		}
		if cfg.IsRootNamespaceBased {
			result[nodeName] = &runtimeNodeGroup{
				name:               nodeName,
				rootNamespaceBased: true,
			}
			continue
		}
		if !cfg.SkipUniquenessCheck || node.GetContainerStatus(ctx) == clabruntime.NotFound {
			continue
		}
		result[nodeName] = &runtimeNodeGroup{name: nodeName, external: true}
	}

	if len(duplicates) > 0 {
		sort.Strings(duplicates)
		return nil, fmt.Errorf(
			"apply supports only single-container nodes, found multiple containers for nodes: %s",
			strings.Join(duplicates, ", "),
		)
	}

	for _, group := range result {
		sort.Slice(group.containers, func(i, j int) bool {
			return runtimeContainerLess(group.containers[i], group.containers[j])
		})
	}

	return result, nil
}

// NeedsInitialDeploy reports whether the lab has no runtime state yet, i.e. whether
// Deploy would perform a fresh deployment instead of reconciling a running lab.
func (c *CLab) NeedsInitialDeploy(ctx context.Context) (bool, error) {
	if c.LabRuntime != nil {
		checker, ok := c.LabRuntime.(clablabruntime.LabExistenceChecker)
		if !ok {
			return false, fmt.Errorf(
				"lab runtime %q cannot determine whether the lab already exists",
				c.globalRuntimeName,
			)
		}
		exists, err := checker.LabExists(ctx, clablabruntime.InspectRequest{
			Name:     c.Config.Name,
			Identity: c.labRuntimeIdentity,
		})

		return !exists, err
	}

	currentNodes, err := c.runtimeNodeGroups(ctx)
	if err != nil {
		return false, err
	}

	return c.needsInitialDeploy(currentNodes)
}

func (c *CLab) needsInitialDeploy(currentNodes map[string]*runtimeNodeGroup) (bool, error) {
	if len(currentNodes) == 0 {
		return true, nil
	}
	for _, node := range currentNodes {
		if !node.external && !node.rootNamespaceBased {
			return false, nil
		}
	}

	state, err := c.LoadState()
	return state == nil, err
}

func (c *CLab) setMgmtBridgeFromRuntime(
	currentNodes map[string]*runtimeNodeGroup,
) error {
	if c.Config.Mgmt.Bridge != "" {
		return nil
	}

	var bridge string
	for _, runtimeNode := range currentNodes {
		for _, ctr := range runtimeNode.containers {
			// only containers attached to the default management network, or
			// without a runtime network, carry the default network's bridge
			// label. Unknown networks, e.g. ones dropped from the mgmt list,
			// must not contribute their bridge.
			switch ctr.NetworkName {
			case "", c.Config.Mgmt.Network:
			default:
				continue
			}
			ctrBridge := ctr.Labels[clabconstants.NodeMgmtNetBr]
			if ctrBridge == "" {
				continue
			}
			if bridge == "" {
				bridge = ctrBridge
				continue
			}
			if bridge != ctrBridge {
				return fmt.Errorf(
					"runtime lab has conflicting management bridge labels: %q and %q",
					bridge,
					ctrBridge,
				)
			}
		}
	}

	if bridge != "" {
		c.Config.Mgmt.Bridge = bridge
	}

	return nil
}

func (c *CLab) updateRuntimeInfoForExistingNodes(ctx context.Context) error {
	for _, nodeName := range sortedNodeNames(c.Nodes) {
		node := c.Nodes[nodeName]
		if node.GetContainerStatus(ctx) == clabruntime.NotFound {
			continue
		}
		if err := node.UpdateConfigWithRuntimeInfo(ctx); err != nil {
			return fmt.Errorf("failed to update runtime info for node %q: %w", nodeName, err)
		}
	}

	return nil
}

func sortedRuntimeNodeGroupNames(nodes map[string]*runtimeNodeGroup) []string {
	names := make([]string, 0, len(nodes))
	for name := range nodes {
		names = append(names, name)
	}
	sort.Strings(names)
	return names
}

func runtimeContainerNodeName(ctr clabruntime.GenericContainer) string {
	if name := ctr.Labels[clabconstants.NodeName]; name != "" {
		return name
	}
	if len(ctr.Names) > 0 {
		return ctr.Names[0]
	}
	return ctr.ID
}

func runtimeContainerLess(a, b clabruntime.GenericContainer) bool {
	// internal holders own the network namespace of the other containers in the group,
	// so they sort first to be deleted last.
	aInternal := a.Labels[clabconstants.InternalNode] == "true"
	bInternal := b.Labels[clabconstants.InternalNode] == "true"
	if aInternal != bInternal {
		return aInternal
	}

	aName := runtimeContainerNodeName(a)
	bName := runtimeContainerNodeName(b)

	aOrder := runtimeComponentSortOrder(aName)
	bOrder := runtimeComponentSortOrder(bName)
	if aOrder != bOrder {
		return aOrder < bOrder
	}

	return aName < bName
}

func runtimeComponentSortOrder(name string) int {
	idx := strings.LastIndex(name, "-")
	if idx < 0 || idx == len(name)-1 {
		return 0
	}

	slot := strings.ToUpper(name[idx+1:])
	if len(slot) == 1 && slot[0] >= 'A' && slot[0] <= 'Z' {
		return 100 - int(slot[0])
	}

	var n int
	for _, r := range slot {
		if r < '0' || r > '9' {
			return 0
		}
		n = n*10 + int(r-'0')
	}

	return n
}

