		o(n)
	}

	if n.Cfg.NodeType != "" && !strings.Contains(n.Cfg.NodeType, "-") {
		log.Warn(
			"Deprecation notice",
			"notice",
			"You are using a deprecated SR Linux node type name. "+
				"Consider using a new format with dashes. Example: ixr-d2l, ixr-h5-64d, etc.\n"+
				"Deprecated type format will be removed after January 2026",
			"deprecated type",
			n.Cfg.NodeType,
		)
	}

	if n.Cfg.NodeType == "" {
		n.Cfg.NodeType = SRLinuxDefaultType
	}

	if _, found := srlTypes[n.Cfg.NodeType]; !found {
		keys := make([]string, 0, len(srlTypes))
		for key := range srlTypes {
			keys = append(keys, key)
		}

		return fmt.Errorf("wrong node type. '%s' doesn't exist. should be any of %s",
			n.Cfg.NodeType, strings.Join(keys, ", "))
	}

	// fail on an unusable components block here rather than midway through the deploy
	if _, err := resolveSRLTopology(n.Cfg); err != nil {
		return err
	}

	if len(n.kindSpecificCfg().Components) > 1 {
		log.Warn("Multiple line cards are rendered into the SR Linux topology file, but "+
			"deploying a node with more than one line card is not supported yet",
			"node", n.Cfg.ShortName, "line cards", len(n.kindSpecificCfg().Components))
	}

	if n.Cfg.Cmd == "" {
		// set default Cmd if it was not provided by a user
		// the additional touch is needed to support non docker runtimes
		n.Cfg.Cmd = "sudo -E bash -c 'touch /.dockerenv && /opt/srlinux/bin/sr_linux'"
	}

	n.Cfg.Env = clabutils.MergeStringMaps(srlEnv, n.Cfg.Env)

	// if user was not initialized to a value, use root
	if n.Cfg.User == "" {
		n.Cfg.User = "0:0"
	}

	// restart the node when it is rebooted from within.
	// unless-stopped is used, as some images exit with code 0 on reboot;
	// on-failure is enough once all supported images exit with a non-zero code.
	if n.Cfg.RestartPolicy == "" {
		n.Cfg.RestartPolicy = "unless-stopped"
	}

	maps.Copy(n.Cfg.Sysctls, srlSysctl)

	if n.Cfg.License != "" {
		// we mount a fixed path node.Labdir/license.key as the license referenced in topo file will
		// be copied to that path
		n.Cfg.Binds = append(n.Cfg.Binds, fmt.Sprint(
			filepath.Join(n.Cfg.LabDir, "license.key"), ":/opt/srlinux/etc/license.key:ro"))
	}

	// mount config directory
	cfgPath := filepath.Join(n.Cfg.LabDir, "config")
	n.Cfg.Binds = append(n.Cfg.Binds, fmt.Sprint(cfgPath, ":/etc/opt/srlinux/:rw"))

	// mount srlinux topology
	srcTopoPath := filepath.Join(n.Cfg.LabDir, "topology.yml")
	dstTopoPath := "/tmp/topology.yml"
	// if a user provided a topology file, it means that they want to use a custom srl topology file
	// in that case we do not need to mount the one for the provided type
	if !clabutils.DestinationBindMountExists(n.Cfg.Binds, dstTopoPath) {
		n.Cfg.Binds = append(n.Cfg.Binds, fmt.Sprint(srcTopoPath, ":", dstTopoPath, ":ro"))
	}

	// mounting /run/netnns as tmpfs ensures the network-instances
	// namespaces don't persist through stop/start/restarts.
	if n.Cfg.Tmpfs == nil {
		n.Cfg.Tmpfs = map[string]string{}
	}

	n.Cfg.Tmpfs["/run/netns"] = "rw,nosuid,nodev,noexec"

	n.InterfaceRegexp = InterfaceRegexp
	n.InterfaceHelp = InterfaceHelp

	return n.initNetnsNode()
}

func (n *srl) PreDeploy(ctx context.Context, params *clabnodes.PreDeployParams) error {
	clabutils.CreateDirectory(n.Cfg.LabDir, clabconstants.PermissionsOpen)

	// store provided pubkeys
	n.sshPubKeys = params.SSHPubKeys

	// store the certificate-related parameters
	// for cert generation to happen in Post-Deploy phase with mgmt IPs as SANs
	n.cert = params.Cert
	n.topologyName = params.TopologyName

	// platform specific pre-deploy actions
	// modular chassis boot in the mode required by the line card generation they are populated
	// with, unless the user pinned the mode explicitly.
	if n.Config().Env["SRL_CHASSIS_MODE"] == "" {
		topology, err := resolveSRLTopology(n.Cfg)
		if err != nil {
			return err
		}

		if topology.ChassisMode != "" {
			n.Config().Env["SRL_CHASSIS_MODE"] = topology.ChassisMode
		}
	}

	return n.createSRLFiles()
}

func (n *srl) Deploy(ctx context.Context, params *clabnodes.DeployParams) error {
	if n.netnsNode == nil {
		return n.DefaultNode.Deploy(ctx, params)
	}

	// network settings are finalized after Init, so the holder config is rebuilt here.
	*n.netnsNode.Config() = *n.newNetnsConfig()
	if err := n.netnsNode.Deploy(ctx, params); err != nil {
		return fmt.Errorf("deploy network namespace node %q: %w", n.netnsNode.GetShortName(), err)
	}

	n.Cfg.Env[clabconstants.ClabEnvIntfs] = strconv.Itoa(len(n.GetEndpoints()))

	cID, err := n.Runtime.CreateContainer(ctx, n.containerConfig())
	if err != nil {
		return err
	}

	if _, err := n.Runtime.StartContainer(ctx, cID, n); err != nil {
		return err
	}

	if err := n.linkNetns(ctx); err != nil {
		return err
	}

	n.SetState(clabnodesstate.Deployed)

	return nil
}

func (n *srl) Start(ctx context.Context) error {
	if n.netnsNode == nil {
		return n.DefaultNode.Start(ctx)
	}

	if err := n.netnsNode.EnsureRunning(ctx, n.Cfg.ShortName); err != nil {
		return err
	}

	if err := n.DefaultNode.Start(ctx); err != nil {
		return err
	}

	return n.linkNetns(ctx)
}

// Stop also stops the holder, so that the next start gets a fresh network namespace without
// interfaces left behind by the stopped SR Linux container.
func (n *srl) Stop(ctx context.Context) error {
	if err := n.DefaultNode.Stop(ctx); err != nil || n.netnsNode == nil {
		return err
	}

	if n.netnsNode.GetContainerStatus(ctx) != clabruntime.Running {
		return nil
	}

	return n.Runtime.StopContainer(ctx, n.netnsNode.Config().LongName, n.netnsNode.StopSignal)
}

func (n *srl) Delete(ctx context.Context) error {
	if n.netnsNode == nil {
		return n.DefaultNode.Delete(ctx)
	}

	return errors.Join(n.DefaultNode.Delete(ctx), n.netnsNode.Delete(ctx))
}

// GetContainers returns the SR Linux container with the network settings of the holder.
// When only the holder exists, it is returned so that it is not orphaned on destroy.
func (n *srl) GetContainers(ctx context.Context) ([]clabruntime.GenericContainer, error) {
	cnts, err := n.DefaultNode.GetContainers(ctx)
	if n.netnsNode == nil {
		return cnts, err
	}

	if err != nil {
		if errors.Is(err, clabnodes.ErrContainersNotFound) {
			return n.netnsNode.GetContainers(ctx)
		}

		return nil, err
	}

	holder, err := n.netnsNode.GetContainers(ctx)
	if err != nil {
		if errors.Is(err, clabnodes.ErrContainersNotFound) {
			return cnts, nil
		}

		return nil, err
	}

	cnts[0].NetworkName = holder[0].NetworkName
	cnts[0].NetworkSettings = holder[0].NetworkSettings
	cnts[0].Ports = holder[0].Ports

	return cnts, nil
}

func (n *srl) PostDeploy(ctx context.Context, params *clabnodes.PostDeployParams) error {
	log.Info("Running postdeploy actions",
		"kind", n.Cfg.Kind,
		"node", n.Cfg.ShortName)

	// generate the certificate
	certificate, err := n.LoadOrGenerateCertificate(n.cert, n.topologyName)
	if err != nil {
		return err
	}

	// set the certificate data
	n.Config().TLSCert = string(certificate.Cert)
	n.Config().TLSKey = string(certificate.Key)

	// Populate /etc/hosts for service discovery on mgmt interface
	if err := n.populateHosts(ctx, params.Nodes); err != nil {
		log.Warnf("Unable to populate hosts for node %q: %v", n.Cfg.ShortName, err)
	}

	// start waiting for initial commit and mgmt server ready
	if err := n.Ready(ctx); err != nil {
		return err
	}

	n.swVersion, err = n.RunningVersion(ctx)
	if err != nil {
		return err
	}

	n.supportsOpenconfig, err = n.OpenConfigFeatureEnabled(ctx)
	if err != nil {
		return err
	}

	// return if config file is found in the lab directory.
	// This can be either if the startup-config has been mounted by that path
	// or the config has been previously generated and saved
	if clabutils.FileExists(filepath.Join(n.Cfg.LabDir, "config", "config.json")) {
		return nil
	}

	if err := n.addDefaultConfig(ctx); err != nil {
		return err
	}

	if err := n.addOverlayCLIConfig(ctx); err != nil {
		return err
	}

	// once default and overlay config is added, we can commit the config
	if err := n.commitConfig(ctx); err != nil {
		return err
	}

	return n.generateCheckpoint(ctx)
}

func (n *srl) SaveConfig(ctx context.Context) (*clabnodes.SaveConfigResult, error) {
	cmd, _ := clabexec.NewExecCmdFromString(saveCmd)

	execResult, err := n.RunExec(ctx, cmd)
	if err != nil {
		return nil, fmt.Errorf("%s: failed to execute cmd: %v", n.Cfg.ShortName, err)
	}

	if execResult.GetStdErrString() != "" {
		return nil, fmt.Errorf("%s errors: %s", n.Cfg.ShortName, execResult.GetStdErrString())
	}

